writescan.py.source:
"""AST scanner: for every .py in the worktree, resolve the paths it WRITES.

Not 'mentions' -- writes. A write site is open(...,'w'|'a'|'x'), .write_text,
.write_bytes, .to_parquet/.to_csv/.to_json, pq.write_table, Path(...).open('w'),
or a call to a writer-helper function discovered in this same corpus (a def whose
body writes its own first parameter, e.g. graph_lib.write_json).

Path arguments resolve through: string constants; module-level constants of ANY
scanned module (cross-module, since scripts do `G.STATUS_REPORT_PATH`);
Path(__file__).resolve().parent chains; f-strings (unknown slot -> '*');
os.path.join; pathlib '/' chains; str.format; % formatting.
Unresolvable arguments are emitted as null so no negative is silent.
"""
import ast, os, sys, json

ROOT = "C:/Users/jgallagher/wnba-betting-model/.claude/worktrees/player-model-program"
WRITE_MODES = ("w", "a", "x")
METHOD_WRITERS = {"write_text": 0, "write_bytes": 0, "to_parquet": 0, "to_csv": 0,
                  "to_json": 0, "to_feather": 0, "write_table": 1, "savefig": 0}


def norm(p):
    return p.replace("\\", "/").replace("//", "/")


class Resolver:
    """Names resolve from THIS module only. Cross-module constants resolve only
    through a real import alias (`import graph_lib as G` -> G.STATUS_REPORT_PATH).
    A blanket global name table silently fabricates paths -- e.g. `self.root`
    picking up an unrelated module's `root` -- so it is deliberately not used."""

    def __init__(self, module_envs=None, aliases=None, file_path=None):
        self.env = {}
        self.module_envs = module_envs or {}     # module basename -> {name: value}
        self.aliases = aliases or {}             # local alias -> module basename
        self.file_path = file_path

    def get(self, name):
        return self.env.get(name)

    def resolve(self, node, depth=0):
        if depth > 14:
            return None
        r = self._resolve(node, depth)
        return norm(r) if isinstance(r, str) else r

    def _resolve(self, node, depth):
        if isinstance(node, ast.Constant):
            return node.value if isinstance(node.value, str) else None
        if isinstance(node, ast.Name):
            if node.id == "__file__" and self.file_path:
                return self.file_path
            return self.get(node.id)
        if isinstance(node, ast.Attribute):
            if node.attr == "parent":
                base = self.resolve(node.value, depth + 1)
                if isinstance(base, str):
                    return base.rsplit("/", 1)[0] if "/" in base else ""
                return None
            if isinstance(node.value, ast.Name):
                if node.value.id == "self":
                    return self.env.get(node.attr)
                mod = self.aliases.get(node.value.id)
                if mod:
                    return self.module_envs.get(mod, {}).get(node.attr)
            return None
        if isinstance(node, ast.JoinedStr):
            out = []
            for v in node.values:
                if isinstance(v, ast.Constant) and isinstance(v.value, str):
                    out.append(v.value)
                else:
                    out.append("*")
            return "".join(out)
        if isinstance(node, ast.Subscript):
            return None
        if isinstance(node, ast.BinOp):
            l = self.resolve(node.left, depth + 1)
            r = self.resolve(node.right, depth + 1)
            if isinstance(node.op, ast.Div):
                if l is None and r is None:
                    return None
                return f"{l if l is not None else '*'}/{r if r is not None else '*'}"
            if isinstance(node.op, ast.Add):
                if l is None and r is None:
                    return None
                return f"{l if l is not None else '*'}{r if r is not None else '*'}"
            if isinstance(node.op, ast.Mod) and isinstance(l, str):
                return l.replace("%s", "*").replace("%d", "*")
            return None
        if isinstance(node, ast.Call):
            f = node.func
            fname = f.attr if isinstance(f, ast.Attribute) else (f.id if isinstance(f, ast.Name) else None)
            if fname in ("Path", "str"):
                return self.resolve(node.args[0], depth + 1) if node.args else None
            if fname == "join":
                parts = [self.resolve(a, depth + 1) for a in node.args]
                if all(p is None for p in parts):
                    return None
                return "/".join(p if p is not None else "*" for p in parts)
            if fname == "format" and isinstance(f, ast.Attribute):
                base = self.resolve(f.value, depth + 1)
                if isinstance(base, str):
                    out, i = [], 0
                    while i < len(base):
                        if base[i] == "{":
                            j = base.find("}", i)
                            if j < 0:
                                break
                            out.append("*")
                            i = j + 1
                        else:
                            out.append(base[i])
                            i += 1
                    return "".join(out)
            if fname in ("resolve", "absolute", "expanduser") and isinstance(f, ast.Attribute):
                return self.resolve(f.value, depth + 1)
            if fname in ("dirname",) and node.args:            # os.path.dirname(p)
                b = self.resolve(node.args[0], depth + 1)
                return (b.rsplit("/", 1)[0] if isinstance(b, str) and "/" in b else None)
            if fname == "abspath" and node.args:
                return self.resolve(node.args[0], depth + 1)
            if fname in ("with_name", "with_suffix") and isinstance(f, ast.Attribute) and node.args:
                b = self.resolve(f.value, depth + 1)          # Path(x).with_name("y")
                a = self.resolve(node.args[0], depth + 1)
                if isinstance(b, str) and isinstance(a, str):
                    d = b.rsplit("/", 1)[0] if "/" in b else ""
                    if fname == "with_name":
                        return f"{d}/{a}" if d else a
                    return (b.rsplit(".", 1)[0] if "." in b.rsplit("/", 1)[-1] else b) + a
            # path-guard wrappers: assert_in_scope(p), ensure_dir(p), require_path(p) ...
            # unwrap a single-positional-arg call only when the arg itself resolves to
            # something path-shaped, so this never invents a path out of e.g. sha256(x).
            if len(node.args) == 1 and not node.keywords:
                inner = self.resolve(node.args[0], depth + 1)
                if isinstance(inner, str) and ("/" in inner or "." in inner.rsplit("/", 1)[-1]):
                    return inner
        return None

    def learn(self, node):
        if isinstance(node, ast.Assign) and len(node.targets) == 1:
            t = node.targets[0]
            name = t.id if isinstance(t, ast.Name) else (t.attr if isinstance(t, ast.Attribute) else None)
            if name:
                v = self.resolve(node.value)
                if isinstance(v, str):
                    self.env[name] = v
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.value is not None:
            v = self.resolve(node.value)
            if isinstance(v, str):
                self.env[node.target.id] = v


def parse(path):
    try:
        src = open(path, "r", encoding="utf-8", errors="replace").read()
        return src, ast.parse(src)
    except Exception as e:
        return None, e


def import_aliases(tree):
    """local name -> module basename, for `import m`, `import m as A`, `from p import m as A`."""
    out = {}
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                base = a.name.split(".")[-1]
                out[a.asname or base] = base
        elif isinstance(n, ast.ImportFrom):
            for a in n.names:
                out[a.asname or a.name] = a.name.split(".")[-1]
    return out


def module_constants(path, tree, src, module_envs, aliases=None):
    """Constant strings bound in one file (module level and inside classes/functions)."""
    R = Resolver(module_envs, aliases or import_aliases(tree), file_path=norm(os.path.abspath(path)))
    for _ in range(3):                       # fixpoint over forward references
        for n in ast.walk(tree):
            R.learn(n)
    return R.env


def find_writer_helpers(files):
    """def f(p, ...) whose body writes p -> calls to f are write sites at arg 0."""
    helpers = {}
    for path, (src, tree) in files.items():
        for n in ast.walk(tree):
            if not isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            if not n.args.args:
                continue
            p0 = n.args.args[0].arg
            for c in ast.walk(n):
                if not isinstance(c, ast.Call):
                    continue
                f = c.func
                fn = f.attr if isinstance(f, ast.Attribute) else (f.id if isinstance(f, ast.Name) else None)
                hit = False
                if fn == "open" and c.args and isinstance(c.args[0], ast.Name) and c.args[0].id == p0:
                    mode = None
                    if len(c.args) >= 2 and isinstance(c.args[1], ast.Constant):
                        mode = c.args[1].value
                    for kw in c.keywords:
                        if kw.arg == "mode" and isinstance(kw.value, ast.Constant):
                            mode = kw.value.value
                    hit = bool(mode) and any(m in mode for m in WRITE_MODES)
                elif fn in ("write_text", "write_bytes") and isinstance(f, ast.Attribute) \
                        and isinstance(f.value, ast.Name) and f.value.id == p0:
                    hit = True
                if hit:
                    helpers[n.name] = norm(os.path.relpath(path, ROOT))
                    break
    return helpers


def scan(files, module_envs, helpers):
    out = {}
    for path, (src, tree) in files.items():
        rel = norm(os.path.relpath(path, ROOT))
        lines = src.splitlines()
        R = Resolver(module_envs, import_aliases(tree), file_path=norm(os.path.abspath(path)))
        for _ in range(3):
            for n in ast.walk(tree):
                R.learn(n)
        hits = []
        for n in ast.walk(tree):
            if not isinstance(n, ast.Call):
                continue
            f = n.func
            fname = f.attr if isinstance(f, ast.Attribute) else (f.id if isinstance(f, ast.Name) else None)
            arg = None
            kind = None
            if fname == "open":
                if isinstance(f, ast.Attribute):          # Path(x).open('w')
                    mode = R.resolve(n.args[0]) if n.args else None
                    for kw in n.keywords:
                        if kw.arg == "mode":
                            mode = R.resolve(kw.value)
                    if mode and any(m in mode for m in WRITE_MODES):
                        arg, kind = R.resolve(f.value), f"open(mode={mode!r})"
                else:
                    mode = R.resolve(n.args[1]) if len(n.args) >= 2 else None
                    for kw in n.keywords:
                        if kw.arg == "mode":
                            mode = R.resolve(kw.value)
                    if mode and any(m in mode for m in WRITE_MODES):
                        arg = R.resolve(n.args[0]) if n.args else None
                        kind = f"open(mode={mode!r})"
            elif fname in METHOD_WRITERS:
                idx = METHOD_WRITERS[fname]
                if fname in ("write_text", "write_bytes"):
                    arg = R.resolve(f.value) if isinstance(f, ast.Attribute) else None
                elif len(n.args) > idx:
                    arg = R.resolve(n.args[idx])
                kind = fname + "()"
            elif fname in helpers:
                arg = R.resolve(n.args[0]) if n.args else None
                kind = f"{fname}() [writer helper defined in {helpers[fname]}]"
            if kind:
                snip = lines[n.lineno - 1].strip() if 0 < n.lineno <= len(lines) else ""
                hits.append({"target": arg, "line": n.lineno, "kind": kind, "src": snip[:200]})
        if hits:
            out[rel] = hits
    return out


def collect(root=ROOT):
    files, errors = {}, {}
    for dp, dn, fn in os.walk(root):
        if ".git" in dp.split(os.sep) or "__pycache__" in dp:
            continue
        for f in fn:
            if f.endswith(".py"):
                p = os.path.join(dp, f)
                src, tree = parse(p)
                if src is None:
                    errors[norm(os.path.relpath(p, root))] = str(tree)
                else:
                    files[p] = (src, tree)
    return files, errors


def main():
    files, errors = collect()
    module_envs = {}
    for path, (src, tree) in files.items():                # pass 1: own constants
        module_envs[os.path.splitext(os.path.basename(path))[0]] =             module_constants(path, tree, src, {})
    for path, (src, tree) in files.items():                # pass 2: resolve X.Y
        module_envs[os.path.splitext(os.path.basename(path))[0]] =             module_constants(path, tree, src, module_envs)
    helpers = find_writer_helpers(files)
    sites = scan(files, module_envs, helpers)
    here = os.path.dirname(os.path.abspath(__file__))
    json.dump({"write_sites": sites, "helpers": helpers, "parse_errors": errors},
              open(os.path.join(here, "write_sites.json"), "w", encoding="utf-8"), indent=1)
    tot = sum(len(v) for v in sites.values())
    unres = sum(1 for v in sites.values() for h in v if h["target"] is None)
    print(f"scanned {len(files)} .py ({len(errors)} unparseable); {len(sites)} files write; "
          f"{tot} write sites; {unres} unresolved; {len(helpers)} writer helpers: {sorted(helpers)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

classify.py.source:
"""Re-measure DERIVED vs HAND_MAINTAINED for every path in DOCUMENT_INDEX.json.

Three independent evidence channels, all measured against bytes:

  W  WRITE_SITE      an AST-resolved write of this exact path in a .py
                     (writescan.py; self-tested by selftest_writescan.py)
  T  TEMPLATE_EMIT   a distinctive line of this file's own bytes appears verbatim
                     as a string literal inside a .py that writes files -- this
                     catches generators whose output path is data-driven
  S  SELF_DECLARED   a generation marker in this file's OWN bytes that survives a
                     REFERENT TEST: the marker must not be talking about a
                     different file. This is the channel the parent index got
                     wrong.

DERIVED requires (W or T or S) AND a named generator.
HAND_MAINTAINED is the result of all three channels coming back empty.
UNDETERMINED is reserved for: derived-looking with no nameable generator.
"""
import ast, hashlib, json, os, re, sys

ROOT = "C:/Users/jgallagher/wnba-betting-model/.claude/worktrees/player-model-program"
HERE = os.path.dirname(os.path.abspath(__file__))
INDEX = os.path.join(ROOT, "experiments/player_program/orchestration/reports/DOCUMENT_INDEX.json")

TEXT_EXT = {".md", ".json", ".jsonl", ".py", ".sha256", ".txt"}

MARKERS = [
    (r"this file is generated", "this file is generated"),
    (r"auto-?generated", "auto-generated"),
    (r"\bgenerated by\b", "generated by"),
    (r"\bgenerated from\b", "generated from"),
    (r"\bregenerated by\b", "regenerated by"),
    (r"\bregenerate[sd]? from\b", "regenerated from"),
    (r"do not hand-?edit", "do not hand-edit"),
    (r"do not edit (this file )?by hand", "do not edit by hand"),
    (r"never hand-?edited", "never hand-edited"),
    (r"derived_not_maintained", "derived_not_maintained"),
    (r"re-?run the generator", "re-run the generator"),
    (r"\bemitted by\b", "emitted by"),
    (r"\bwritten by\b", "written by"),
    (r"\bproduced by\b", "produced by"),
]
# "emitted/written/produced by" is ordinary prose about some other artifact. It is
# admitted only when the same sentence names THIS file. Every other marker asserts
# generation of the artifact that contains it.
WEAK = {"emitted by", "written by", "produced by"}

# An explicit "this file is generated ..." is self-referential no matter what other
# filename the sentence goes on to name -- the named file is the SOURCE, not the
# subject. Without this, "This file is GENERATED from the node's contract in
# PROGRAM_GRAPH.json" would be rejected as talking about PROGRAM_GRAPH.json.
SELF_ANCHOR = re.compile(
    r"\bthis\s+(file|document|index|report|artifact)\s+(is|was)\s+"
    r"(auto-?)?(generated|derived|regenerated|emitted|produced)"
    r"|\bdo not (hand-?edit|edit) this (file|document)", re.I)

FILEISH = re.compile(r"[A-Za-z0-9_./\\-]+\.(?:md|json|jsonl|py|parquet|csv|sha256|txt)\b")
DECL_JSON_KEYS = {"derived_not_maintained", "generated_by", "generator", "generated_at",
                  "generated_at_utc", "produced_by", "emitted_by"}


def is_test(script):
    b = script.rsplit("/", 1)[-1].lower()
    return b.startswith("test") or b == "tests.py" or "selftest" in b


def sha256(p):
    h = hashlib.sha256()
    with open(p, "rb") as fh:
        for b in iter(lambda: fh.read(1 << 20), b""):
            h.update(b)
    return h.hexdigest()


def norm(p):
    return p.replace("\\", "/")


# ------------------------------------------------------------------ channel W
def load_write_sites():
    d = json.load(open(os.path.join(HERE, "write_sites.json"), encoding="utf-8"))
    exact, wildcard = {}, []
    for script, hits in d["write_sites"].items():
        for h in hits:
            t = h["target"]
            if not isinstance(t, str):
                continue
            t = norm(t)
            if t.lower().startswith(ROOT.lower()):
                t = t[len(ROOT):].lstrip("/")
            if "*" in t:
                wildcard.append((script, t, h))
            else:
                exact.setdefault(t, []).append((script, h))
    return exact, wildcard, d


def write_evidence(relpath, exact, wildcard):
    """A write target counts only when it identifies THIS path.

    A bare 'REPORT.md' (a script writing next to itself) is credited only to a
    file in that script's own directory -- several nodes each emit a REPORT.md,
    and basename equality would attribute one node's report to another.
    """
    ev = []
    for t, lst in exact.items():
        for script, h in lst:
            sdir = script.rsplit("/", 1)[0]
            if t == relpath:
                why = "exact path"
            elif "/" not in t and relpath == f"{sdir}/{t}":
                why = "bare filename resolved against the writing script's own directory"
            else:
                continue
            ev.append({"channel": "WRITE_SITE", "generator": script, "line": h["line"],
                       "call": h["kind"], "resolved_target": t, "match": why,
                       "source_line": h["src"]})
    return ev


# ------------------------------------------------------------------ channel T
def script_write_scopes():
    """{py_rel: [concrete path or wildcard prefix it writes]} -- used to require that
    a template match comes from a script that could actually write to that path."""
    sites = json.load(open(os.path.join(HERE, "write_sites.json"), encoding="utf-8"))["write_sites"]
    out = {}
    for rel, hits in sites.items():
        scopes = []
        for h in hits:
            t = h["target"]
            if not isinstance(t, str):
                continue
            t = norm(t)
            if t.lower().startswith(ROOT.lower()):
                t = t[len(ROOT):].lstrip("/")
            if "*" in t:
                pre = t.split("*", 1)[0]
                scopes.append(("UNKNOWN_BASE", t) if pre == "" and not h["target"].lower().startswith(ROOT.lower())
                              else ("PREFIX", pre))
            else:
                scopes.append(("EXACT", t))
        out[rel] = scopes
    return out


def can_write(scopes, relpath):
    for kind, v in scopes:
        if kind == "EXACT" and v == relpath:
            return True
        if kind == "PREFIX" and (v == "" or relpath.startswith(v)):
            return True
    return False


def py_literals():
    """{py_rel: joined string literals} for every .py that writes anything."""
    sites = json.load(open(os.path.join(HERE, "write_sites.json"), encoding="utf-8"))["write_sites"]
    out = {}
    for rel in sites:
        p = os.path.join(ROOT, rel)
        try:
            tree = ast.parse(open(p, encoding="utf-8", errors="replace").read())
        except Exception:
            continue
        lits = []
        for n in ast.walk(tree):
            if isinstance(n, ast.Constant) and isinstance(n.value, str) and len(n.value) >= 30:
                lits.append(n.value)
        if lits:
            out[rel] = "\n<<>>\n".join(lits)
    return out


def candidate_lines(text, ext):
    """Distinctive lines from a document, used to look for a template emitter."""
    lines = [l.strip() for l in text.splitlines()]
    lines = [l for l in lines if len(l) >= 45 and not l.startswith("|") and "://" not in l]
    lines.sort(key=len, reverse=True)
    return lines[:30]


# ------------------------------------------------------------------ channel S
def strip_fences(lines):
    out, infence = [], False
    for i, l in enumerate(lines):
        if l.lstrip().startswith("```"):
            infence = not infence
            continue
        if not infence:
            out.append((i + 1, l))
    return out


def self_declaration(relpath, text, ext):
    """Markers in the file's own bytes that survive the referent test."""
    own = relpath.rsplit("/", 1)[-1]
    accepted, rejected = [], []

    # JSON: only TOP-LEVEL declaration keys count. A marker buried in a nested
    # value is the file talking about something else -- exactly the parent's bug.
    if ext == ".json":
        try:
            obj = json.load(open(os.path.join(ROOT, relpath), encoding="utf-8"))
        except Exception:
            obj = None
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k.lower() in DECL_JSON_KEYS:
                    rec = {"channel": "SELF_DECLARED", "where": f"top-level key {k!r}",
                           "verbatim": (f'"{k}": ' + json.dumps(v))[:400]}
                    if k.lower() in ("generated_by", "generator", "produced_by", "emitted_by") \
                            and isinstance(v, str):
                        rec["declared_generator"] = v[:200]
                    accepted.append(rec)
            # record near-misses for audit
            blob = json.dumps(obj)
            for rx, name in MARKERS:
                for m in re.finditer(rx, blob, re.I):
                    seg = blob[max(0, m.start() - 90): m.end() + 90]
                    if not accepted:
                        rejected.append({"marker": name, "where": "nested value (not a top-level declaration)",
                                         "verbatim": seg[:220]})
                    break
            return accepted, rejected[:4]
        return accepted, rejected

    # .py: a marker inside a string literal is the script EMITTING that text into
    # something else, not declaring itself generated. Only the module docstring
    # can self-declare. (retrospective_gate_audit.py prints "*Generated by
    # retrospective_gate_audit.py*" into its own output -- that is not evidence
    # that the script is generated.)
    if ext == ".py":
        try:
            doc = ast.get_docstring(ast.parse(text)) or ""
        except Exception:
            doc = ""
        for i, l in enumerate(doc.splitlines(), 1):
            for rx, name in MARKERS:
                if name in WEAK:
                    continue
                if re.search(rx, l, re.I):
                    accepted.append({"channel": "SELF_DECLARED",
                                     "where": f"module docstring line {i}",
                                     "verbatim": l.strip()[:300]})
                    break
        if not accepted:
            for rx, name in MARKERS:
                m = re.search(rx, text, re.I)
                if m:
                    rejected.append({"marker": name,
                                     "where": "string literal or comment in the source, not the module docstring",
                                     "verbatim": text[max(0, m.start() - 80): m.end() + 80].strip()[:220]})
        return accepted, rejected[:4]

    lines = strip_fences(text.splitlines())
    nonblank = [i for i, (ln, l) in enumerate(lines) if l.strip()]
    head_cut = lines[nonblank[min(len(nonblank) - 1, 24)]][0] if nonblank else 0
    tail_cut = lines[-8][0] if len(lines) > 8 else 0

    for ln, l in lines:
        for rx, name in MARKERS:
            if not re.search(rx, l, re.I):
                continue
            named = set(FILEISH.findall(l))
            named = {n for n in named}
            others = {n for n in named if n.rsplit("/", 1)[-1] != own}
            mine = {n for n in named if n.rsplit("/", 1)[-1] == own}
            rec = {"marker": name, "line": ln, "verbatim": l.strip()[:300]}
            if SELF_ANCHOR.search(l):
                accepted.append({"channel": "SELF_DECLARED", "where": f"line {ln}",
                                 "verbatim": l.strip()[:300],
                                 "referent": "explicit self-anchor ('this file is generated ...'); any filename in the sentence is the SOURCE, not the subject"})
            elif mine:
                rec["referent"] = "names THIS file"
                accepted.append({"channel": "SELF_DECLARED", "where": f"line {ln}",
                                 "verbatim": l.strip()[:300], "referent": "names this file"})
            elif others:
                rec["referent"] = f"names other file(s): {sorted(others)} -- NOT a self-declaration"
                rejected.append(rec)
            elif name in WEAK:
                rec["referent"] = "weak marker ('%s') naming no file -> ordinary prose, rejected" % name
                rejected.append(rec)
            else:
                if ln <= head_cut or ln >= tail_cut:
                    rec["referent"] = "unqualified marker in header/footer position -> reads as self-declaration"
                    accepted.append({"channel": "SELF_DECLARED", "where": f"line {ln} (header/footer)",
                                     "verbatim": l.strip()[:300], "referent": "unqualified, positional"})
                else:
                    rec["referent"] = "unqualified marker in body -> referent unknown, rejected"
                    rejected.append(rec)
            break
    return accepted, rejected[:6]


def generator_from_text(evlist):
    """Pull a script/command name out of a self-declaration."""
    names = []
    for e in evlist:
        if e.get("declared_generator"):
            names.append(e["declared_generator"])
        for tok in FILEISH.findall(e.get("verbatim", "")):
            if tok.endswith(".py"):
                names.append(tok)
        m = re.search(r"[Gg]enerated by ([^.;\"]+)", e.get("verbatim", ""))
        if m and not names:
            names.append(m.group(1).strip().strip("`*"))
        m = re.search(r"GENERATED from ([^.;\"]+)", e.get("verbatim", ""))
        if m and not names:
            names.append("template render from " + m.group(1).strip().strip("`*"))
    seen, out = set(), []
    for n in names:
        if n not in seen:
            seen.add(n)
            out.append(n)
    return out


def main():
    idx = json.load(open(INDEX, encoding="utf-8"))
    exact, wildcard, raw = load_write_sites()
    lits = py_literals()
    scopes = script_write_scopes()

    index_paths = {norm(d["path"]) for d in idx["documents"]}
    records, drift, missing = [], [], []
    for d in idx["documents"]:
        rel = norm(d["path"])
        abspath = os.path.join(ROOT, rel)
        ext = os.path.splitext(rel)[1].lower()
        if not os.path.exists(abspath):
            missing.append(rel)
            continue
        h = sha256(abspath)
        if h != d["sha256"]:
            drift.append({"path": rel, "index_sha256": d["sha256"], "measured_sha256": h})

        ev, rejected = [], []
        ev += write_evidence(rel, exact, wildcard)

        text = None
        if ext in TEXT_EXT and os.path.getsize(abspath) < 8 << 20:
            text = open(abspath, encoding="utf-8", errors="replace").read()

        if text is not None:
            # TEMPLATE_EMIT: >=2 distinct long lines of this document must appear
            # verbatim as string literals in ONE .py, and that .py must have a
            # write site that could reach this path. Both conditions are needed:
            # one shared line is quotation, and a script that cannot write here
            # did not produce it.
            cls = candidate_lines(text, ext)
            for py, blob in lits.items():
                if py == rel or not can_write(scopes.get(py, []), rel):
                    continue
                hits_ = [c for c in cls if c in blob]
                if len(hits_) >= 2:
                    ev.append({"channel": "TEMPLATE_EMIT", "generator": py,
                               "matched_lines": [h[:180] for h in hits_[:3]],
                               "n_matched_lines": len(hits_),
                               "write_scope_of_generator": [f"{k}:{v}" for k, v in scopes.get(py, [])][:4],
                               "note": "these lines of the document exist verbatim as string literals in a .py whose write scope covers this path"})
                    break
            acc, rej = self_declaration(rel, text, ext)
            ev += acc
            rejected += rej

            # RENDERED_FROM: a .md that is the human-readable twin of an indexed
            # .json is derived from it. Measured by counting the sha256 tokens the
            # .md shares with the .json -- a renderer copies them, a writer does not.
            if ext == ".md":
                twin = rel[:-3] + ".json"
                tp = os.path.join(ROOT, twin)
                if os.path.exists(tp) and twin in index_paths:
                    hexes = set(re.findall("[0-9a-f]{64}", text))
                    tj = open(tp, encoding="utf-8", errors="replace").read()
                    shared = {h for h in hexes if h in tj}
                    if len(hexes) >= 20 and len(shared) >= 0.9 * len(hexes):
                        e = {"channel": "RENDERED_FROM", "renders": twin,
                             "sha256_tokens_in_md": len(hexes),
                             "also_present_in_json": len(shared),
                             "note": "human-readable twin: this .md reproduces the digests carried by the .json, so it is rendered from it, not typed"}
                        try:
                            tobj = json.loads(tj)
                            for k in ("generated_by", "generator", "produced_by"):
                                if isinstance(tobj, dict) and isinstance(tobj.get(k), str):
                                    e["generator"] = tobj[k]
                                    e["generator_source"] = f"inherited from {twin} top-level key {k!r}"
                                    break
                        except Exception:
                            pass
                        ev.append(e)

        # Write targets whose directory part did not resolve statically. Matched as
        # globs, with a LOCALITY guard: the writing script must live in a directory
        # that contains the target, or the target must have a rooted prefix. Basename
        # alone is not enough -- several lanes each emit their own MANIFEST.json.
        probable = []
        for script, t, h in wildcard:
            # the target must still name a concrete FILE. A bare '*' (a fully
            # data-driven path, e.g. generate_prompts.py's) matches everything and
            # would make its own directory's source files look generated.
            tail = t.rsplit("*", 1)[-1].rsplit("/", 1)[-1]
            if "." not in tail or tail == "":
                continue
            sdir = script.rsplit("/", 1)[0] + "/"
            rooted = not t.startswith("*")
            if not (rooted or rel.startswith(sdir)):
                continue
            if not re.fullmatch(re.escape(t).replace(r"\*", ".*"), rel):
                continue
            probable.append({"channel": "WRITE_SITE_WILDCARD", "generator": script,
                             "line": h["line"], "call": h["kind"], "resolved_target": t,
                             "source_line": h["src"], "confidence": "probable",
                             "is_test_script": is_test(script),
                             "caveat": "the directory part of this write target was not statically resolvable; it is matched as a glob under the locality rule"})
        # a test fixture writing a path-shaped temp copy is not a generator of the
        # real artifact; keep it visible but do not let it alone force DERIVED
        strong_probable = [e for e in probable if not e["is_test_script"]]
        ev += strong_probable
        unestablished = [e for e in probable if e["is_test_script"]]

        gens = sorted({e["generator"] for e in ev if "generator" in e})
        # a prose declaration only supplies the generator NAME when no channel has
        # already identified an actual producing script
        decl_gens = [] if gens else generator_from_text(
            [e for e in ev if e["channel"] == "SELF_DECLARED"])
        all_gens = gens + [g for g in decl_gens if g not in gens]

        if ev and all_gens:
            m = "DERIVED"
        elif ev and not all_gens:
            m = "UNDETERMINED"
        else:
            m = "HAND_MAINTAINED"

        # append-only ledgers are machine-written but NOT regenerable. Calling them
        # simply DERIVED is the same class of hazard as calling a contract DERIVED.
        appended = [e for e in ev if "mode='a" in str(e.get("call", ""))
                    or "append_jsonl" in str(e.get("call", ""))]
        if m == "DERIVED":
            discipline = "APPEND_ONLY_NOT_REGENERABLE" if appended else "REGENERATED_BY_GENERATOR"
        else:
            discipline = "HUMAN_EDITED"

        records.append({
            "path": rel, "sha256": h, "size_bytes": os.path.getsize(abspath),
            "maintenance": m, "generator": all_gens, "write_discipline": discipline,
            "evidence": ev,
            "rejected_markers": rejected,
            "not_established": unestablished,
            "index_maintenance": d["maintenance"],
            "index_evidence": d["maintenance_evidence"],
        })

    json.dump({"records": records, "drift": drift, "missing": missing},
              open(os.path.join(HERE, "classified.json"), "w", encoding="utf-8"), indent=1)

    from collections import Counter
    print("measured:", Counter(r["maintenance"] for r in records))
    print("index    :", Counter(r["index_maintenance"] for r in records))
    ch = Counter(c["channel"] for r in records for c in r["evidence"])
    print("evidence channels:", ch)
    changed = [r for r in records if r["maintenance"] != r["index_maintenance"]]
    print(f"reclassified: {len(changed)} of {len(records)}")
    print(f"drift: {len(drift)}  missing: {len(missing)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

